
const path = require("path");
const mammoth = require("mammoth");

const { processDocument } = require("./Services/DocumentProcessor");
const { createChunks } = require("./Services/ChunkingService");

// Test DOCX heading extraction and chunking.
const testDocx = async () => {
    try {
        const filePath = path.join(
            __dirname,
            "Sample-Documents",
            "Backend all Topic.docx"
        );

        // Preview the HTML generated by Mammoth.
        const result = await mammoth.convertToHtml({
            path: filePath,
        });

        console.log("\n========== MAMMOTH HTML PREVIEW ==========\n");
        console.log(result.value.substring(0, 3000));

        // Extract document sections.
        const document = await processDocument(filePath);

        console.log("\nDocument:", document.fileName);
        console.log("Extracted Sections:", document.content.length);

        // Display extracted headings.
        console.log("\n========== EXTRACTED HEADINGS ==========\n");

        const headings = [
            ...new Set(
                document.content.map((section) => section.heading)
            ),
        ];

        headings.forEach((heading) => console.log("-", heading));

        // Generate chunks with heading metadata.
        const chunks = createChunks(document);

        console.log("\nGenerated Chunks:", chunks.length);

        // Display first five chunks.
        console.log("\n========== FIRST FIVE CHUNKS ==========\n");

        chunks.slice(0, 5).forEach((chunk) => {
            console.log({
                chunkIndex: chunk.chunkIndex,
                heading: chunk.heading,
                tokenCount: chunk.tokenCount,
                textPreview: chunk.text.substring(0, 150),
            });
        });

        console.log("\n========================================\n");

    } catch (error) {
        console.error("DOCX Test Failed:", error.message);
    }
};

testDocx();
